+		wantErrEnv  string
+	}{
+		{
+			name:        "with Helm release",
+			namespace:   "test",
+			replicaName: "agent-0",
+			releaseName: "release",
+		},
+		{
+			name:        "without Helm release",
+			namespace:   "test",
+			replicaName: "agent-0",
+		},
+		{
+			name:        "missing namespace",
+			replicaName: "agent-0",
+			wantErrEnv:  NamespaceEnv,
+		},
+		{
+			name:       "missing replica name",
+			namespace:  "test",
+			wantErrEnv: teleportReplicaNameEnv,
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			t.Setenv(NamespaceEnv, tt.namespace)
+			t.Setenv(teleportReplicaNameEnv, tt.replicaName)
+			t.Setenv(ReleaseNameEnv, tt.releaseName)
+
+			client := fake.NewSimpleClientset()
+			b, err := NewWithClient(client)
+			if tt.wantErrEnv != "" {
+				require.EqualError(t, err, fmt.Sprintf("environment variable %q not set or empty", tt.wantErrEnv))
+				require.Nil(t, b)
+				return
+			}
+
+			require.NoError(t, err)
+			require.Equal(t, tt.namespace, b.Namespace)
+			require.Equal(t, tt.replicaName, b.ReplicaName)
+			require.Equal(t, tt.replicaName+"-state", b.SecretName)
+			require.Equal(t, tt.releaseName, b.ReleaseName)
+			require.Same(t, client, b.KubeClient)
+		})
+	}
